mapper.select:
SELECT consumer_name, tenant_id, aggregate_type, aggregate_id, last_version, last_ordinal
FROM inbox_consumer_position
WHERE consumer_name = #{consumerName}
  AND tenant_id = #{tenantId}
  AND aggregate_type = #{aggregateType}
  AND aggregate_id = #{aggregateId}

SELECT outcome
FROM inbox_event
WHERE consumer_name = #{consumerName}
  AND event_id = #{eventId}

SELECT min(lower(l.planned_range)) AS "from", max(upper(l.planned_range)) AS "to"
FROM reservation_line l
WHERE l.tenant_id = #{tenantId}
  AND l.hotel_id = #{hotelId}
  AND l.reservation_id = #{reservationId}
